/**
 * Calculates the maximum number of characters that fit on one line given a
 * font size and container width. Uses an approximate average character width
 * of 0.55 * fontSize for sans-serif text. Adjust the factor if needed.
 * Returns 0 if we cannot reliably estimate (e.g., width <= 0).
 */
function getMaxCharactersForOneLine(
  widthPx: number,
  fontSizePt: number,
  paddingPx: number = 16,
  charWidthFactor: number = 0.55,
): number {
  if (widthPx <= 0 || fontSizePt <= 0) return 0;
  const usableWidth = Math.max(0, widthPx - 2 * paddingPx);
  const charWidthPx = fontSizePt * charWidthFactor; // rough approximation
  return Math.max(1, Math.floor((usableWidth - 4) / charWidthPx)); // -4 for ellipsis buffer
