function shouldTruncate(text: string, options: AutoTruncateOptions): boolean {
  if (!options.autoTruncate) return false;
  const maxChars = getMaxCharactersForOneLine(
    options.containerWidth ?? 0,
    options.fontSize ?? Platform.select({ ios: 17, android: 16 }),
  );
  return text.length > maxChars;
}

