**Helper: `computeEstimatedHeight`**

```ts
function computeEstimatedHeight(
  text: string,
  widthPx: number,
  fontSizePt: number,
  charWidthFactor: number,
  lineHeightRatio: number = LINE_HEIGHT_RATIO,
  verticalPadding: number = 4,
  lineGap: number = 4,
): number {
  if (widthPx <= 0) return 0;
  const usableWidth = Math.max(0, widthPx - 8); // 4px each side
  const charsPerLine = Math.max(10, Math.floor(usableWidth / (fontSizePt * charWidthFactor)));
  const trimmed = text.trim();
  const lines = trimmed.length === 0 ? 0 : Math.ceil(trimmed.length / charsPerLine);
  if (lines === 0) return verticalPadding;
  const lineHeight = fontSizePt * lineHeightRatio;
  const contentHeight = lines * lineHeight + (lines > 1 ? (lines - 1) * lineGap : 0);
  return contentHeight + verticalPadding * 2;
}
```

