```tsx
function truncateText(text: string, maxLines: number, ellipsis = '…'): string {
  if (!text) return '';
  // Estimate max characters for the given number of lines
  // We use the same heuristic as estimateLines to find the cutoff.
  const width = effectiveWidth - horizontalPadding * 2;
  const cpl = Math.max(10, Math.floor(width / (realFontSize * charWidthFactor)));
  const maxChars = maxLines * cpl;
  let trimmed = text.trimEnd();
  if (trimmed.length === 0) return '';
  if (trimmed.length <= maxChars) return text; // No truncation needed
  // Cut at last space, or if none, cut at maxChars
  let endIdx = Math.min(maxChars, trimmed.length);
  if (endIdx > 3) {
    const lastSpace = trimmed.lastIndexOf(' ', endIdx);
    if (lastSpace > 0) endIdx = lastSpace;
  }
  return trimmed.substring(0, endIdx) + ellipsis;
}
```

