  text: string,
  maxLines: number,
  widthPx: number,
  fontSizePt: number,
  charWidthFactor: number,
): string {
  if (!text) return '';
  const usableWidth = Math.max(0, widthPx - 8); // 4px each side
  const cpl = Math.max(10, Math.floor(usableWidth / (fontSizePt * charWidthFactor)));
