const DEFAULT_CONTAINER_WIDTH = 300; // px
const DEFAULT_CHAR_WIDTH_FACTOR = 0.62;
const DEFAULT_COLLAPSED_HEIGHT = 56; // px
const LABEL_HEIGHT = 16;
const GAPPED = 4;
const EXPAND_SLIDE_OFFSET = -8; // px (text slides in from above)

