export function ExpandText({
  text,
  numberOfLines,
  label = 'See more',
  labelCollapsed = 'Show less',
  initialExpanded,
  autoTruncate = true,
  containerWidth,
  fontSize,
  charWidthFactor = DEFAULT_CHAR_WIDTH_FACTOR,
  verticalPadding = 4,
  horizontalPadding = 8,
  animationDuration = 300,
  animationEasing = 'easeOut',
  collapsedHeight,
  maxExpandedHeight,
  onChange,
  onExpandStart,
  onCollapseStart,
  textStyle,
  labelStyle,
